const ADMIN = "<!DOCTYPE html>\n<html lang=\"uz\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Boshqaruv — abduraximov.uz</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700&family=Manrope:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#02040A;--panel:#0A1426;--panel2:#0E1A30;--line:rgba(160,255,230,.16);--aur:#00FFC6;--cy:#38E1FF;--vi:#B04BFF;--bad:#FF5C7A;--tx:#EAF7FF;--tx2:#A9BED0;--tx3:#6F8598;\n  --f-d:'Unbounded',system-ui,sans-serif;--f-b:'Manrope',system-ui,sans-serif;--f-m:'JetBrains Mono',ui-monospace,monospace;color-scheme:dark}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nbody{margin:0;min-height:100vh;background:radial-gradient(900px 500px at 15% -10%,rgba(0,255,198,.12),transparent 60%),radial-gradient(900px 500px at 100% 0%,rgba(176,75,255,.12),transparent 60%),var(--ink);color:var(--tx);font:400 15px/1.55 var(--f-b)}\n.wrap{max-width:1040px;margin:0 auto;padding:0 max(18px,env(safe-area-inset-right,0px)) 60px max(18px,env(safe-area-inset-left,0px))}\nheader{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 0}\n.brand{display:flex;align-items:center;gap:10px;font:500 12px var(--f-m);letter-spacing:.18em;text-transform:uppercase;color:var(--tx);text-decoration:none}\n.brand svg{width:28px;height:28px}\nh1{font:500 24px/1.2 var(--f-d);letter-spacing:-.02em;margin:0}\n.btn{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:rgba(6,14,28,.6);color:var(--tx);border-radius:999px;padding:10px 16px;font:600 14px var(--f-b);cursor:pointer;text-decoration:none}\n.btn:hover{border-color:rgba(0,255,198,.55)}\n.btn.pri{border-color:transparent;color:var(--ink);background:linear-gradient(100deg,var(--aur),var(--cy))}\n.btn.sm{padding:7px 12px;font-size:13px}\n.btn.del{color:var(--bad)}\n.card{background:linear-gradient(160deg,rgba(14,26,46,.75),rgba(6,12,24,.7));border:1px solid var(--line);border-radius:22px;padding:22px}\n.login{max-width:440px;margin:12vh auto 0;text-align:center;display:grid;gap:16px;justify-items:center}\n.login p{margin:0;color:var(--tx2)}\n.msg{font:500 13px var(--f-m);color:var(--aur);min-height:1.4em}\n.tabs{display:flex;gap:6px;padding:5px;border:1px solid var(--line);border-radius:999px;width:max-content;max-width:100%;overflow-x:auto;margin:6px 0 20px;background:rgba(6,14,28,.5)}\n.tabs button{border:0;background:none;color:var(--tx2);padding:8px 16px;border-radius:999px;font:600 14px var(--f-b);cursor:pointer;white-space:nowrap}\n.tabs button[aria-pressed=\"true\"]{background:var(--aur);color:var(--ink)}\n.head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}\n.items{display:grid;gap:10px}\n.item{display:flex;align-items:center;gap:14px;padding:14px 16px;border-radius:16px;border:1px solid var(--line);background:var(--panel)}\n.item.off{opacity:.55}\n.item .t{flex:1;min-width:0}\n.item b{display:block;font-weight:700}\n.item small{display:block;color:var(--tx3);font:400 12.5px var(--f-m);overflow-wrap:anywhere}\n.pill{flex:none;font:500 11.5px var(--f-m);padding:3px 9px;border-radius:999px;border:1px solid var(--line);color:var(--tx2)}\n.pill.live{color:var(--aur);border-color:rgba(0,255,198,.45)}\n.acts{display:flex;gap:6px;flex-wrap:wrap}\n.empty{padding:22px;border:1px dashed var(--line);border-radius:16px;color:var(--tx3);text-align:center}\n.tbl{width:100%;border-collapse:collapse;font-size:14px}\n.tw{overflow-x:auto;border:1px solid var(--line);border-radius:16px}\n.tbl th,.tbl td{padding:10px 12px;text-align:left;border-bottom:1px solid rgba(160,255,230,.08);white-space:nowrap}\n.tbl th{font:500 12px var(--f-m);letter-spacing:.06em;text-transform:uppercase;color:var(--tx3);background:var(--panel2)}\n.tbl a{color:var(--aur)}\ndialog{border:1px solid var(--line);border-radius:22px;background:#081224;color:var(--tx);padding:22px;width:min(560px,calc(100% - 24px))}\ndialog::backdrop{background:rgba(0,0,0,.6);backdrop-filter:blur(4px)}\nform{display:grid;gap:12px}\nlabel{display:grid;gap:5px;font:600 13px var(--f-b);color:var(--tx2)}\nlabel small{font-weight:400;color:var(--tx3)}\ninput[type=text],input[type=url],input[type=number],textarea,select{width:100%;border:1px solid var(--line);background:#050C1A;color:var(--tx);border-radius:12px;padding:10px 12px;font:400 15px var(--f-b)}\ntextarea{min-height:90px;resize:vertical}\n.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.chk{display:flex;align-items:center;gap:8px;font-weight:600}\n.foot{display:flex;justify-content:flex-end;gap:8px;margin-top:6px}\n.err{color:var(--bad);font-size:13px;min-height:1.2em;margin:0}\n.toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);background:#0E1A30;border:1px solid var(--line);padding:10px 16px;border-radius:999px;font-size:14px}\n:focus-visible{outline:2px solid var(--aur);outline-offset:2px}\n@media (max-width:560px){.row{grid-template-columns:1fr}.item{flex-wrap:wrap}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <a class=\"brand\" href=\"/\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#00FFC6\"/><stop offset=\"1\" stop-color=\"#B04BFF\"/></linearGradient></defs><rect x=\"1\" y=\"1\" width=\"62\" height=\"62\" rx=\"16\" fill=\"#02040A\" stroke=\"rgba(160,255,230,.25)\"/><path d=\"M10 46 L24 26 L32 36 L40 22 L54 46\" fill=\"none\" stroke=\"url(#g)\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></svg>abduraximov.uz · boshqaruv</a>\n    <button class=\"btn sm\" type=\"button\" id=\"out\" hidden>Chiqish</button>\n  </header>\n  <main id=\"app\"></main>\n</div>\n<script>\n(function(){\n'use strict';\nvar app = document.getElementById('app'), T = null, tab = 'proj';\ntry { T = sessionStorage.getItem('abd_adm'); } catch (e) {}\nvar esc = function(s){ return String(s == null ? '' : s).replace(/[&<>\"']/g, function(c){ return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); };\nfunction toast(m){ var d = document.createElement('div'); d.className = 'toast'; d.textContent = m; document.body.appendChild(d); setTimeout(function(){ d.remove(); }, 2600); }\nfunction api(p, body){ return fetch('/api/admin/' + p, { method: body ? 'POST' : 'GET', headers: Object.assign({ 'content-type': 'application/json' }, T ? { authorization: 'Bearer ' + T } : {}), body: body ? JSON.stringify(body) : undefined })\n  .then(function(r){ return r.json().then(function(j){ if (r.status === 401) { setT(null); render(); throw new Error('auth'); } return j; }); }); }\nfunction setT(t){ T = t; try { t ? sessionStorage.setItem('abd_adm', t) : sessionStorage.removeItem('abd_adm'); } catch (e) {} document.getElementById('out').hidden = !t; }\ndocument.getElementById('out').onclick = function(){ api('logout', {}).catch(function(){}); setT(null); render(); };\n\nfunction login(){\n  app.innerHTML = '<div class=\"card login\"><h1>Boshqaruv paneli</h1><p>Kirish Telegram bot orqali tasdiqlanadi. Faqat sayt egasi kira oladi.</p><button class=\"btn pri\" type=\"button\" id=\"tgb\">Telegram orqali kirish</button><a class=\"btn\" id=\"tgl\" target=\"_blank\" rel=\"noopener\" hidden>Telegram\\'ni ochish</a><div class=\"msg\" id=\"lm\" role=\"status\"></div></div>';\n  var lm = document.getElementById('lm'), poll = null;\n  document.getElementById('tgb').onclick = function(){\n    lm.textContent = '…';\n    api('login', {}).then(function(j){\n      if (!j.code || !j.bot) { lm.textContent = j.error === 'too_many' ? 'Biroz kuting va qayta bosing.' : 'Bot hali sozlanmagan.'; return; }\n      var url = 'https://t.me/' + j.bot + '?start=adm_' + j.code, a = document.getElementById('tgl'); a.href = url; a.hidden = false;\n      try { window.open(url, '_blank', 'noopener'); } catch (e) {}\n      lm.textContent = 'Telegram\\'da «Start»ni bosing, keyin shu sahifaga qayting…';\n      clearInterval(poll); var n = 0;\n      poll = setInterval(function(){\n        if (++n > 150) { clearInterval(poll); lm.textContent = 'Vaqt tugadi. Qaytadan bosing.'; return; }\n        fetch('/api/admin/login?code=' + j.code).then(function(r){ return r.json(); }).then(function(s){\n          if (s.status === 'ok') { clearInterval(poll); setT(s.token); render(); }\n          else if (s.status === 'expired') { clearInterval(poll); lm.textContent = 'Havola eskirdi. Qaytadan bosing.'; }\n        }).catch(function(){});\n      }, 2000);\n    }).catch(function(){ lm.textContent = 'Xatolik. Internetni tekshiring.'; });\n  };\n}\n\nfunction render(){\n  if (!T) return login();\n  document.getElementById('out').hidden = false;\n  app.innerHTML = '<nav class=\"tabs\" aria-label=\"Boʻlimlar\"><button type=\"button\" data-t=\"proj\" aria-pressed=\"' + (tab === 'proj') + '\">Loyihalar</button><button type=\"button\" data-t=\"geo\" aria-pressed=\"' + (tab === 'geo') + '\">Joylashuvlar</button></nav><section id=\"pane\"></section>';\n  app.querySelectorAll('[data-t]').forEach(function(b){ b.onclick = function(){ tab = b.dataset.t; render(); }; });\n  if (tab === 'proj') projects(); else geos();\n}\nvar STX = { live: 'Ishlamoqda', soon: 'Tez orada', plan: 'Rejada' };\nfunction projects(){\n  var pane = document.getElementById('pane'); pane.innerHTML = '<div class=\"empty\">Yuklanmoqda…</div>';\n  api('projects').then(function(j){\n    var L = j.projects || [];\n    pane.innerHTML = '<div class=\"head\"><h1>Loyihalar</h1><button class=\"btn pri\" type=\"button\" id=\"add\">+ Yangi loyiha</button></div><div class=\"items\">' +\n      (L.length ? L.map(function(p){ return '<div class=\"item' + (p.visible ? '' : ' off') + '\"><div class=\"t\"><b>' + esc(p.title) + '</b><small>' + esc(p.url || 'havolasiz') + ' · tartib ' + p.sort + (p.visible ? '' : ' · yashirin') + '</small></div><span class=\"pill ' + esc(p.status) + '\">' + esc(STX[p.status] || p.status) + '</span><div class=\"acts\"><button class=\"btn sm\" type=\"button\" data-e=\"' + p.id + '\">Tahrirlash</button><button class=\"btn sm del\" type=\"button\" data-d=\"' + p.id + '\">Oʻchirish</button></div></div>'; }).join('') : '<div class=\"empty\">Loyiha yoʻq.</div>') +\n      '</div><p style=\"color:var(--tx3);font-size:13px;margin-top:14px\">«Hamkorlik» kartasi saytda doim oxirida turadi. Tartib raqami kattasi oldinda chiqadi.</p>';\n    document.getElementById('add').onclick = function(){ form({ status: 'live', sort: 0, visible: 1 }); };\n    pane.querySelectorAll('[data-e]').forEach(function(b){ b.onclick = function(){ form(L.find(function(p){ return p.id == b.dataset.e; })); }; });\n    pane.querySelectorAll('[data-d]').forEach(function(b){ b.onclick = function(){\n      if (b.dataset.sure) { api('project-del', { id: +b.dataset.d }).then(function(){ toast('Oʻchirildi'); projects(); }); }\n      else { b.dataset.sure = 1; b.textContent = 'Rostdanmi?'; setTimeout(function(){ if (b.isConnected) { delete b.dataset.sure; b.textContent = 'Oʻchirish'; } }, 3000); } }; });\n  }).catch(function(){});\n}\nfunction form(p){\n  var d = document.createElement('dialog');\n  d.innerHTML = '<h1 style=\"margin-bottom:14px\">' + (p.id ? 'Loyihani tahrirlash' : 'Yangi loyiha') + '</h1><form id=\"f\" novalidate>' +\n    '<label>Nomi<input type=\"text\" id=\"f_title\" name=\"title\" maxlength=\"80\" required value=\"' + esc(p.title) + '\"></label>' +\n    '<label>Qisqa tavsif<textarea id=\"f_text\" name=\"text\" maxlength=\"400\">' + esc(p.text) + '</textarea></label>' +\n    '<label>Havola <small>https:// bilan boshlansin. Boʻsh qoldirsangiz, karta bosilmaydi.</small><input type=\"url\" id=\"f_url\" name=\"url\" maxlength=\"300\" placeholder=\"https://\" value=\"' + esc(p.url) + '\"></label>' +\n    '<label>Teglar <small>vergul bilan: Testlar, Viktorina</small><input type=\"text\" id=\"f_tags\" name=\"tags\" maxlength=\"200\" value=\"' + esc(p.tags) + '\"></label>' +\n    '<div class=\"row\"><label>Holati<select id=\"f_status\" name=\"status\"><option value=\"live\">Ishlamoqda</option><option value=\"soon\">Tez orada</option><option value=\"plan\">Rejada</option></select></label>' +\n    '<label>Tartib raqami<input type=\"number\" id=\"f_sort\" name=\"sort\" value=\"' + esc(p.sort || 0) + '\"></label></div>' +\n    '<label class=\"chk\"><input type=\"checkbox\" id=\"f_vis\" name=\"visible\"' + (p.visible === 0 ? '' : ' checked') + '> Saytda koʻrsatish</label>' +\n    '<p class=\"err\" id=\"ferr\" aria-live=\"polite\"></p><div class=\"foot\"><button class=\"btn\" type=\"button\" id=\"fc\">Bekor qilish</button><button class=\"btn pri\" type=\"submit\">Saqlash</button></div></form>';\n  document.body.appendChild(d); d.querySelector('#f_status').value = p.status || 'live'; d.showModal();\n  d.querySelector('#fc').onclick = function(){ d.close(); };\n  d.addEventListener('close', function(){ d.remove(); });\n  d.querySelector('#f').onsubmit = function(e){\n    e.preventDefault(); var f = e.target, er = d.querySelector('#ferr');\n    var b = { id: p.id, title: f.title.value.trim(), text: f.text.value.trim(), url: f.url.value.trim(), tags: f.tags.value.trim(), status: f.status.value, sort: +f.sort.value || 0, visible: f.visible.checked };\n    if (!b.title) { er.textContent = 'Nomini kiriting.'; return; }\n    if (b.url && !/^https:\\/\\//.test(b.url)) { er.textContent = 'Havola https:// bilan boshlanishi kerak.'; return; }\n    api('project', b).then(function(j){ if (j.ok) { d.close(); toast('Saqlandi'); projects(); } else er.textContent = 'Saqlab boʻlmadi: ' + (j.error || ''); }).catch(function(){});\n  };\n}\nfunction geos(){\n  var pane = document.getElementById('pane'); pane.innerHTML = '<div class=\"empty\">Yuklanmoqda…</div>';\n  api('geo').then(function(j){\n    var L = j.geo || [], fmt = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', dateStyle: 'short', timeStyle: 'short' });\n    pane.innerHTML = '<div class=\"head\"><h1>Joylashuvlar</h1><span style=\"color:var(--tx3);font-size:13px\">Faqat rozilik bergan tashrifchilar · oxirgi 300 ta</span></div>' +\n      (L.length ? '<div class=\"tw\"><table class=\"tbl\"><thead><tr><th>Vaqt</th><th>Koordinata</th><th>Aniqlik</th><th>Hudud</th><th>Qurilma</th><th></th></tr></thead><tbody>' +\n        L.map(function(g){ var c = (+g.lat).toFixed(5) + ', ' + (+g.lon).toFixed(5); return '<tr><td>' + fmt.format(new Date(g.created * 1000)) + '</td><td><a href=\"https://maps.google.com/?q=' + (+g.lat) + ',' + (+g.lon) + '\" target=\"_blank\" rel=\"noopener\">' + c + '</a></td><td>±' + (+g.acc) + ' m</td><td>' + esc(g.place) + '</td><td>' + esc(g.device) + '</td><td><button class=\"btn sm del\" type=\"button\" data-g=\"' + g.id + '\">Oʻchirish</button></td></tr>'; }).join('') + '</tbody></table></div>'\n        : '<div class=\"empty\">Hozircha joylashuv yuborilmagan.</div>');\n    pane.querySelectorAll('[data-g]').forEach(function(b){ b.onclick = function(){ api('geo-del', { id: +b.dataset.g }).then(function(){ toast('Oʻchirildi'); geos(); }); }; });\n  }).catch(function(){});\n}\nrender();\n})();\n</script>\n</body>\n</html>\n";
const LEGAL = "<!DOCTYPE html>\n<html lang=\"uz\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Huquqiy maʼlumot — abduraximov.uz</title>\n<meta name=\"robots\" content=\"index, follow\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%2300FFC6'/%3E%3Cstop offset='1' stop-color='%23B04BFF'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='64' height='64' rx='16' fill='%2302040A'/%3E%3Cpath d='M10 46 L24 26 L32 36 L40 22 L54 46' fill='none' stroke='url(%23g)' stroke-width='5' stroke-linejoin='round' stroke-linecap='round'/%3E%3C/svg%3E\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700&family=Manrope:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#02040A;--line:rgba(160,255,230,.16);--aur:#00FFC6;--cy:#38E1FF;--vi:#B04BFF;--tx:#EAF7FF;--tx2:#A9BED0;--tx3:#6F8598;\n  --f-d:'Unbounded',system-ui,sans-serif;--f-b:'Manrope',system-ui,sans-serif;--f-m:'JetBrains Mono',ui-monospace,monospace;color-scheme:dark}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{scroll-behavior:smooth;background:var(--ink)}\nbody{margin:0;min-height:100vh;color:var(--tx);font:400 16px/1.7 var(--f-b);-webkit-font-smoothing:antialiased;\n  background:radial-gradient(1100px 600px at 12% -10%,rgba(0,255,198,.1),transparent 60%),radial-gradient(1000px 600px at 100% 0%,rgba(176,75,255,.12),transparent 60%),var(--ink)}\na{color:var(--aur)}\n.wrap{max-width:820px;margin:0 auto;padding:0 max(20px,env(safe-area-inset-left,0px)) 80px max(20px,env(safe-area-inset-right,0px))}\nheader{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:22px 0;flex-wrap:wrap}\n.brand{display:flex;align-items:center;gap:10px;font:500 12px var(--f-m);letter-spacing:.16em;text-transform:uppercase;color:var(--tx);text-decoration:none}\n.brand svg{width:28px;height:28px}\n.lang{display:flex;gap:2px;padding:4px;border:1px solid var(--line);border-radius:999px;background:rgba(4,10,20,.5)}\n.lang button{border:0;background:none;color:var(--tx3);font:600 11px var(--f-m);letter-spacing:.1em;padding:5px 10px;border-radius:999px;cursor:pointer}\n.lang button[aria-pressed=\"true\"]{background:var(--aur);color:var(--ink)}\nh1{font:700 clamp(30px,5vw,52px)/1.05 var(--f-d);letter-spacing:-.03em;margin:30px 0 6px}\n.upd{font:500 12.5px var(--f-m);color:var(--tx3);letter-spacing:.06em;margin:0 0 10px}\n.tabs{display:flex;gap:8px;margin:22px 0 10px;flex-wrap:wrap}\n.tabs a{text-decoration:none;border:1px solid var(--line);border-radius:999px;padding:9px 16px;font:600 14px var(--f-b);color:var(--tx2)}\n.tabs a.on{border-color:transparent;color:var(--ink);background:linear-gradient(100deg,var(--aur),var(--cy))}\nsection{padding:26px 0;border-top:1px solid rgba(160,255,230,.1)}\nh2{font:500 clamp(22px,3vw,30px)/1.2 var(--f-d);letter-spacing:-.02em;margin:0 0 6px}\nh3{font:600 17px var(--f-b);margin:22px 0 4px;color:var(--tx)}\np,li{color:var(--tx2)}\nul{padding-left:20px;margin:8px 0}\nli{margin:4px 0}\n.box{border:1px solid var(--line);border-radius:16px;padding:16px 18px;margin:14px 0;background:rgba(6,14,28,.5)}\n.box b{color:var(--aur)}\n.back{display:inline-flex;align-items:center;gap:8px;margin-top:36px;text-decoration:none;color:var(--tx2);font-weight:600}\n.back:hover{color:var(--aur)}\nfooter{border-top:1px solid rgba(160,255,230,.1);padding:24px 0;font:500 12px var(--f-m);letter-spacing:.1em;color:var(--tx3);text-transform:uppercase}\n:focus-visible{outline:2px solid var(--aur);outline-offset:2px}\n[data-lang-block]{display:none}\nhtml[lang=\"uz\"] [data-lang-block=\"uz\"],html[lang=\"en\"] [data-lang-block=\"en\"]{display:block}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <a class=\"brand\" href=\"/\"><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><defs><linearGradient id=\"bg1\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#00FFC6\"/><stop offset=\"1\" stop-color=\"#B04BFF\"/></linearGradient></defs><rect x=\"1\" y=\"1\" width=\"62\" height=\"62\" rx=\"16\" fill=\"#02040A\" stroke=\"rgba(160,255,230,.25)\"/><path d=\"M10 46 L24 26 L32 36 L40 22 L54 46\" fill=\"none\" stroke=\"url(#bg1)\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></svg>abduraximov.uz</a>\n    <div class=\"lang\" role=\"group\" aria-label=\"Til / Language\"><button type=\"button\" data-lang=\"uz\">UZ</button><button type=\"button\" data-lang=\"en\">EN</button></div>\n  </header>\n\n  <!-- ============ UZBEK ============ -->\n  <div data-lang-block=\"uz\">\n    <h1>Huquqiy maʼlumot</h1>\n    <p class=\"upd\">Oxirgi yangilanish: 31-oktabr, 2026-yil</p>\n    <div class=\"tabs\"><a href=\"#maxfiylik\" class=\"on\">Maxfiylik siyosati</a><a href=\"#shartlar\">Foydalanish shartlari</a><a href=\"#xavfsizlik\">Xavfsizlik</a></div>\n\n    <section id=\"maxfiylik\">\n      <h2>Maxfiylik siyosati</h2>\n      <p>Ushbu sayt (abduraximov.uz) tashrifchilarning maʼlumotlarini hurmat qiladi va faqat zarur boʻlgan minimal maʼlumotni yigʻadi. Maʼlumotlarga Oʻzbekiston Respublikasining «Shaxsga doir maʼlumotlar toʻgʻrisida»gi Qonuni talablariga muvofiq ishlov beriladi.</p>\n\n      <h3>Qanday maʼlumot yigʻiladi</h3>\n      <ul>\n        <li><b>Joylashuv.</b> Faqat siz «Ruxsat berish»ni bosib, brauzerda ham ruxsat bergan taqdirda GPS joylashuvingiz (kenglik va uzunlik) olinadi. Ruxsat bermasangiz, hech narsa olinmaydi.</li>\n        <li><b>Taxminiy hudud.</b> IP manzilingiz asosida davlat va shahar aniqlanishi mumkin (IP manzilning oʻzi ochiq saqlanmaydi).</li>\n        <li><b>Qurilma turi.</b> Telefon, kompyuter yoki planshet ekanligi.</li>\n        <li><b>Til tanlovi va rozilik sozlamalaringiz.</b> Faqat sizning brauzeringiz xotirasida saqlanadi.</li>\n      </ul>\n\n      <div class=\"box\"><b>Joylashuv qayerga boradi.</b> Siz rozilik bergan joylashuv sayt egasiga (Abduraximov) Telegram orqali xabar sifatida yuboriladi va saytning maʼlumotlar bazasida saqlanadi. U boshqa shaxslarga, tashkilotlarga yoki reklama beruvchilarga berilmaydi, sotilmaydi.</div>\n\n      <h3>Nima uchun</h3>\n      <p>Joylashuv sayt egasiga tashrifchilar qayerdan kirayotganini bilish uchun kerak. Boshqa maqsadda ishlatilmaydi.</p>\n\n      <h3>Cookie va brauzer xotirasi</h3>\n      <p>Sayt reklama yoki kuzatuv (tracking) cookie fayllaridan foydalanmaydi. Brauzer xotirasida faqat ikki narsa saqlanadi: til tanlovingiz va rozilik sozlamangiz. Shuning uchun «Rad etish»ni bossangiz ham sayt ishlashida hech narsa oʻzgarmaydi. Bularni brauzer sozlamalarida istalgan vaqtda oʻchirishingiz mumkin.</p>\n\n      <h3>Saqlash muddati</h3>\n      <p>Yuborilgan joylashuvlar sayt egasi ularni oʻchirmaguncha saqlanadi. Sayt egasi boshqaruv panelidan istalgan yozuvni oʻchira oladi.</p>\n\n      <h3>Sizning huquqlaringiz</h3>\n      <ul>\n        <li>Roziligingizni istalgan vaqtda qaytarib olish (brauzer sozlamalaridan yoki sahifa pastidagi «Joylashuv sozlamasi» orqali).</li>\n        <li>Siz haqingizda saqlangan maʼlumotni oʻchirishni soʻrash.</li>\n      </ul>\n      <p>Buning uchun <a href=\"/#aloqa\">«Aloqa»</a> boʻlimidagi manzil orqali yozing.</p>\n    </section>\n\n    <section id=\"shartlar\">\n      <h2>Foydalanish shartlari</h2>\n      <p>Saytdan foydalanish orqali siz quyidagi shartlarga rozilik bildirasiz.</p>\n      <ul>\n        <li>Sayt shaxsiy maqsadda, maʼlumot berish uchun yaratilgan. Undagi matn va dizayn abduraximov.uz uchun tayyorlangan.</li>\n        <li>Saytga zarar yetkazish, uni buzishga urinish, avtomatik hujumlar yoki ruxsatsiz kirishga urinish taqiqlanadi.</li>\n        <li>«Loyihalar» boʻlimidagi havolalar boshqa saytlarga olib boradi; oʻsha saytlarning mazmuni uchun ularning egalari javobgar.</li>\n        <li>Sayt «boricha» taqdim etiladi; uzluksiz ishlashi kafolatlanmaydi.</li>\n      </ul>\n    </section>\n\n    <section id=\"xavfsizlik\">\n      <h2>Xavfsizlik</h2>\n      <ul>\n        <li>Sayt butunlay <b>HTTPS</b> orqali, shifrlangan ulanishda ishlaydi.</li>\n        <li>Boshqaruv paneliga faqat sayt egasi Telegram orqali kira oladi; parol saqlanmaydi.</li>\n        <li>Sayt hech qachon sizdan parol, SMS kod, karta maʼlumotlari yoki toʻlov soʻramaydi.</li>\n        <li>Agar kimdir abduraximov.uz nomidan pul yoki maxfiy maʼlumot soʻrasa, bu firibgarlik — javob bermang.</li>\n      </ul>\n    </section>\n    <a class=\"back\" href=\"/\">← Bosh sahifaga qaytish</a>\n  </div>\n\n  <!-- ============ ENGLISH ============ -->\n  <div data-lang-block=\"en\">\n    <h1>Legal information</h1>\n    <p class=\"upd\">Last updated: 31 October 2026</p>\n    <div class=\"tabs\"><a href=\"#maxfiylik\" class=\"on\">Privacy policy</a><a href=\"#shartlar\">Terms of use</a><a href=\"#xavfsizlik\">Security</a></div>\n\n    <section>\n      <h2>Privacy policy</h2>\n      <p>This site (abduraximov.uz) respects visitors' data and collects only the minimum necessary. Data is processed in line with the Personal Data Law of the Republic of Uzbekistan.</p>\n\n      <h3>What is collected</h3>\n      <ul>\n        <li><b>Location.</b> Your GPS location (latitude and longitude) is collected only if you tap «Allow» and also grant permission in your browser. If you don't, nothing is collected.</li>\n        <li><b>Approximate region.</b> Country and city may be inferred from your IP address (the IP itself is not stored in the clear).</li>\n        <li><b>Device type.</b> Whether you're on a phone, computer or tablet.</li>\n        <li><b>Language choice and consent settings.</b> Kept only in your own browser.</li>\n      </ul>\n\n      <div class=\"box\"><b>Where location goes.</b> A location you consent to is sent to the site owner (Abduraximov) as a Telegram message and stored in the site's database. It is not shared with, or sold to, any other person, organisation or advertiser.</div>\n\n      <h3>Why</h3>\n      <p>Location helps the site owner see where visitors come from. It is used for no other purpose.</p>\n\n      <h3>Cookies and browser storage</h3>\n      <p>The site uses no advertising or tracking cookies. Only two things are kept in your browser: your language choice and your consent setting. So pressing «Decline» changes nothing about how the site works. You can clear them in your browser settings at any time.</p>\n\n      <h3>Retention</h3>\n      <p>Submitted locations are kept until the owner deletes them. The owner can remove any entry from the admin panel.</p>\n\n      <h3>Your rights</h3>\n      <ul>\n        <li>Withdraw consent at any time (via browser settings or the «Location settings» link in the footer).</li>\n        <li>Request deletion of data stored about you.</li>\n      </ul>\n      <p>To do so, write via the address in the <a href=\"/#aloqa\">«Contact»</a> section.</p>\n    </section>\n\n    <section>\n      <h2>Terms of use</h2>\n      <p>By using the site you agree to the following.</p>\n      <ul>\n        <li>The site is a personal, informational project. Its text and design were made for abduraximov.uz.</li>\n        <li>Damaging the site, attempting to break it, automated attacks or unauthorised access are prohibited.</li>\n        <li>Links in «Projects» lead to other sites; their owners are responsible for that content.</li>\n        <li>The site is provided «as is»; uninterrupted operation is not guaranteed.</li>\n      </ul>\n    </section>\n\n    <section>\n      <h2>Security</h2>\n      <ul>\n        <li>The site runs entirely over <b>HTTPS</b>, on an encrypted connection.</li>\n        <li>Only the owner can sign in to the admin panel, via Telegram; no password is stored.</li>\n        <li>The site never asks you for a password, SMS code, card details or payment.</li>\n        <li>If anyone asks for money or secrets in the name of abduraximov.uz, it's a scam — don't respond.</li>\n      </ul>\n    </section>\n    <a class=\"back\" href=\"/\">← Back to home</a>\n  </div>\n\n  <footer>© 2026 abduraximov.uz</footer>\n</div>\n<script>\n(function(){\n  var L = 'uz';\n  try { var s = localStorage.getItem('abd_lang'); if (s === 'uz' || s === 'en') L = s; else if ((navigator.language || '').slice(0, 2).toLowerCase() === 'en') L = 'en'; } catch (e) {}\n  function apply(){ document.documentElement.lang = L; document.querySelectorAll('.lang button').forEach(function(b){ b.setAttribute('aria-pressed', String(b.dataset.lang === L)); }); }\n  document.querySelectorAll('.lang button').forEach(function(b){ b.addEventListener('click', function(){ L = b.dataset.lang; try { localStorage.setItem('abd_lang', L); } catch (e) {} apply(); }); });\n  apply();\n  /* Tab highlight */\n  function hi(){ var h = location.hash || '#maxfiylik'; document.querySelectorAll('.tabs a').forEach(function(a){ a.classList.toggle('on', a.getAttribute('href') === h); }); }\n  addEventListener('hashchange', hi); hi();\n})();\n</script>\n</body>\n</html>\n";
const SEC = { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache', 'x-content-type-options': 'nosniff', 'referrer-policy': 'strict-origin-when-cross-origin', 'x-frame-options': 'DENY', 'permissions-policy': 'camera=(), microphone=(), geolocation=(self)' };
const J = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
const esc = v => String(v == null ? '' : v).replace(/[<>&"']/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#39;' }[c]));
const now = () => Math.floor(Date.now() / 1000);
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
const sha = async s => hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)));
const rid = n => hex(crypto.getRandomValues(new Uint8Array(n)));
const S = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, n);
const okUrl = u => { u = S(u, 300); return /^https:\/\/[^\s<>"']+$/.test(u) ? u : ''; };

async function limited(req, tag, sec) {
  const ip = req.headers.get('cf-connecting-ip') || '0';
  const key = new Request('https://rl.abduraximov.uz/' + tag + '/' + encodeURIComponent(ip));
  if (await caches.default.match(key)) return true;
  await caches.default.put(key, new Response('1', { headers: { 'cache-control': 'max-age=' + sec } }));
  return false;
}
async function tg(env, method, body) {
  if (!env.GEO_BOT_TOKEN) return null;
  return fetch('https://api.telegram.org/bot' + env.GEO_BOT_TOKEN + '/' + method, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
}
let BOT = null;
async function botName(env) {
  if (BOT) return BOT; const r = await tg(env, 'getMe', {}); if (!r) return null;
  const j = await r.json().catch(() => ({})); BOT = j.ok ? j.result.username : null; return BOT;
}
const hookSecret = async env => (await sha('hook:' + env.GEO_BOT_TOKEN)).slice(0, 32);

/* ---------- Bosh sahifa: loyihalar serverda joylanadi ---------- */
const ICO = [
  '<path d="M12 3l8 4.5v9L12 21l-8-4.5v-9z"/><path d="M12 12l8-4.5M12 12v9M12 12L4 7.5"/>',
  '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  '<path d="M4 17l6-6 4 4 6-8"/><path d="M14 7h6v6"/>',
  '<rect x="3" y="4" width="18" height="14" rx="3"/><path d="M8 21h8M12 18v3"/>'
];
const ST = { live: ['<b data-i18n="st_live">● Ishlamoqda</b>', ''], soon: ['<span data-i18n="st_soon">Tez orada</span>', ' soon'], plan: ['<span data-i18n="st_plan">Rejada</span>', ' soon'] };
function cards(list) {
  const out = list.map((p, i) => {
    const st = ST[p.status] || ST.plan, url = okUrl(p.url);
    const tags = S(p.tags, 200).split(',').map(t => t.trim()).filter(Boolean).slice(0, 5);
    const host = url ? url.replace(/^https:\/\//, '').replace(/\/$/, '') : '';
    const inner = `<span class="ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICO[i % ICO.length]}</svg></span>
          <h3>${esc(p.title)}</h3>
          <p>${esc(p.text)}</p>
          ${tags.length ? `<div class="tags">${tags.map(t => `<span>${esc(t)}</span>`).join('')}</div>` : ''}
          <div class="meta">${st[0]}<span class="arrow">${url ? esc(host) + ' →' : ''}</span></div>`;
    return url ? `<a class="card rv${st[1]}" href="${esc(url)}" target="_blank" rel="noopener">${inner}</a>`
               : `<div class="card rv${st[1]}" tabindex="0">${inner}</div>`;
  });
  out.push(`<a class="card rv" href="#aloqa" style="--c1:#00FFC6;--c2:#38E1FF">
          <span class="ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M8 12h8M12 8v8"/><rect x="3" y="3" width="18" height="18" rx="5"/></svg></span>
          <h3 data-i18n="c_collab_t">Hamkorlik</h3>
          <p data-i18n="c_collab_p">Birgalikda loyiha qilish yoki gʻoya taklif qilish uchun bogʻlaning.</p>
          <div class="meta"><b data-i18n="c_collab_s">● Ochiq</b><span class="arrow" data-i18n="c_collab_a">Yozish →</span></div>
        </a>`);
  return out.join('\n        ');
}
async function home(req, env) {
  let list = [];
  try { list = (await env.DB.prepare('SELECT * FROM abd_projects WHERE visible = 1 ORDER BY sort DESC, id ASC LIMIT 30').all()).results || []; } catch (e) {}
  const body = HTML.replace('<!--PROJECTS-->', cards(list));
  return new Response(req.method === 'HEAD' ? null : body, { headers: SEC });
}

/* ---------- Joylashuv ---------- */
async function geo(req, env, ctx) {
  if (req.method !== 'POST') return J({ error: 'method' }, 405);
  const o = req.headers.get('origin') || ''; if (o && !/^https:\/\/(www\.)?abduraximov\.uz$/.test(o)) return J({ error: 'origin' }, 403);
  const b = await req.json().catch(() => ({})); const lat = +b.lat, lon = +b.lon, acc = Math.round(+b.acc || 0);
  if (!isFinite(lat) || !isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) return J({ error: 'bad' }, 400);
  if (!env.GEO_BOT_TOKEN || !env.ADMIN_ID) return J({ error: 'not_configured' }, 503);
  if (await limited(req, 'geo', 60)) return J({ error: 'too_many' }, 429);
  const cf = req.cf || {}; const ua = req.headers.get('user-agent') || '';
  const dev = /iPhone|iPad/.test(ua) ? 'iPhone/iPad' : /Android/.test(ua) ? 'Android' : /Windows/.test(ua) ? 'Windows' : /Mac OS/.test(ua) ? 'Mac' : 'Boshqa';
  const place = [cf.city, cf.region, cf.country].filter(Boolean).join(', ');
  const t = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', dateStyle: 'short', timeStyle: 'medium' }).format(new Date());
  const test = b.test === true;
  if (!test) await env.DB.prepare('INSERT INTO abd_geo (lat, lon, acc, place, device, created) VALUES (?, ?, ?, ?, ?, ?)').bind(lat, lon, acc, S(place, 120), dev, now()).run().catch(() => {});
  const text = (test ? '🧪 <b>SINOV XABARI</b>\n' : '') + '📍 <b>abduraximov.uz — yangi joylashuv</b>\nKenglik: <code>' + lat.toFixed(6) + '</code>\nUzunlik: <code>' + lon.toFixed(6) + '</code>\nAniqlik: ±' + acc + ' m\n' +
    'Xarita: https://maps.google.com/?q=' + lat.toFixed(6) + ',' + lon.toFixed(6) + '\nHudud (IP boʻyicha): ' + esc(place) + '\nQurilma: ' + dev + '\nVaqt: ' + t + ' (Toshkent)';
  const r = await tg(env, 'sendMessage', { chat_id: env.ADMIN_ID, text, parse_mode: 'HTML', disable_web_page_preview: true });
  ctx.waitUntil(tg(env, 'sendLocation', { chat_id: env.ADMIN_ID, latitude: lat, longitude: lon }));
  if (r && r.ok) return J({ ok: true });
  const jj = r ? await r.json().catch(() => ({})) : {};
  return J({ error: 'telegram', detail: S(jj.description, 200) }, 502);
}

/* ---------- Telegram bot (admin kirishi) ---------- */
async function hook(req, env) {
  if (req.headers.get('x-telegram-bot-api-secret-token') !== await hookSecret(env)) return new Response('no', { status: 403 });
  const u = await req.json().catch(() => ({})); const m = u.message; if (!m || !m.text || !m.from) return J({ ok: true });
  const from = m.from, text = m.text.trim(), isAdmin = String(from.id) === String(env.ADMIN_ID);
  const mm = text.match(/^\/start\s+adm_([a-f0-9]{24})$/);
  if (mm) {
    if (isAdmin) {
      const r = await env.DB.prepare('UPDATE abd_login SET done = 1 WHERE code = ? AND created > ?').bind(mm[1], now() - 600).run();
      await tg(env, 'sendMessage', { chat_id: m.chat.id, text: r.meta && r.meta.changes ? '✅ abduraximov.uz boshqaruv paneliga kirish tasdiqlandi. Saytga qayting.' : '⌛ Kirish havolasi eskirgan. Saytda qaytadan «Telegram orqali kirish»ni bosing.' });
    } else {
      await tg(env, 'sendMessage', { chat_id: m.chat.id, text: 'Bu boshqaruv paneliga faqat sayt egasi kira oladi.' });
      await tg(env, 'sendMessage', { chat_id: env.ADMIN_ID, text: '⚠️ abduraximov.uz admin paneliga begona urinish: ' + (from.first_name || '') + (from.username ? ' @' + from.username : '') + ' (ID ' + from.id + ')' });
    }
  } else if (/^\/start/.test(text)) {
    await tg(env, 'sendMessage', { chat_id: m.chat.id, text: 'Salom! Bu bot abduraximov.uz sayti uchun. Sayt: https://abduraximov.uz' });
  }
  return J({ ok: true });
}
async function auth(req, env) {
  const h = req.headers.get('authorization') || ''; const t = h.startsWith('Bearer ') ? h.slice(7) : '';
  if (!/^[a-f0-9]{64}$/.test(t)) return false;
  const row = await env.DB.prepare('SELECT created FROM abd_tokens WHERE hash = ?').bind(await sha(t)).first();
  return !!row && row.created > now() - 43200;
}
async function admin(req, env, p) {
  if (p === '/api/admin/login' && req.method === 'POST') {
    if (await limited(req, 'login', 10)) return J({ error: 'too_many' }, 429);
    const code = rid(12); await env.DB.prepare('INSERT INTO abd_login (code, done, created) VALUES (?, 0, ?)').bind(code, now()).run();
    await env.DB.prepare('DELETE FROM abd_login WHERE created < ?').bind(now() - 3600).run();
    return J({ code, bot: await botName(env) });
  }
  if (p === '/api/admin/login' && req.method === 'GET') {
    const code = new URL(req.url).searchParams.get('code') || ''; if (!/^[a-f0-9]{24}$/.test(code)) return J({ status: 'expired' });
    const row = await env.DB.prepare('SELECT * FROM abd_login WHERE code = ? AND created > ?').bind(code, now() - 600).first();
    if (!row) return J({ status: 'expired' }); if (!row.done) return J({ status: 'wait' });
    await env.DB.prepare('DELETE FROM abd_login WHERE code = ?').bind(code).run();
    const tok = rid(32); await env.DB.prepare('INSERT INTO abd_tokens (hash, created) VALUES (?, ?)').bind(await sha(tok), now()).run();
    await env.DB.prepare('DELETE FROM abd_tokens WHERE created < ?').bind(now() - 43200).run();
    return J({ status: 'ok', token: tok });
  }
  if (!(await auth(req, env))) return J({ error: 'auth' }, 401);
  if (p === '/api/admin/logout' && req.method === 'POST') { const t = (req.headers.get('authorization') || '').slice(7); await env.DB.prepare('DELETE FROM abd_tokens WHERE hash = ?').bind(await sha(t)).run(); return J({ ok: true }); }
  if (p === '/api/admin/projects' && req.method === 'GET') return J({ projects: (await env.DB.prepare('SELECT * FROM abd_projects ORDER BY sort DESC, id ASC').all()).results });
  if (p === '/api/admin/project' && req.method === 'POST') {
    const b = await req.json().catch(() => ({})); const title = S(b.title, 80); if (!title) return J({ error: 'title' }, 400);
    const url = S(b.url, 300); if (url && !okUrl(url)) return J({ error: 'url' }, 400);
    const v = [title, S(b.text, 400), url, S(b.tags, 200), ['live', 'soon', 'plan'].includes(b.status) ? b.status : 'plan', Math.max(-999, Math.min(999, parseInt(b.sort) || 0)), b.visible === false ? 0 : 1];
    if (b.id) await env.DB.prepare('UPDATE abd_projects SET title=?, text=?, url=?, tags=?, status=?, sort=?, visible=?, updated=? WHERE id=?').bind(...v, now(), +b.id).run();
    else await env.DB.prepare('INSERT INTO abd_projects (title, text, url, tags, status, sort, visible, created, updated) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(...v, now(), now()).run();
    return J({ ok: true });
  }
  if (p === '/api/admin/project-del' && req.method === 'POST') { const b = await req.json().catch(() => ({})); await env.DB.prepare('DELETE FROM abd_projects WHERE id = ?').bind(+b.id).run(); return J({ ok: true }); }
  if (p === '/api/admin/geo' && req.method === 'GET') return J({ geo: (await env.DB.prepare('SELECT * FROM abd_geo ORDER BY id DESC LIMIT 300').all()).results });
  if (p === '/api/admin/geo-del' && req.method === 'POST') { const b = await req.json().catch(() => ({})); await env.DB.prepare('DELETE FROM abd_geo WHERE id = ?').bind(+b.id).run(); return J({ ok: true }); }
  return J({ error: 'not_found' }, 404);
}

export default {
  async fetch(req, env, ctx) {
    const u = new URL(req.url), p = u.pathname;
    if (u.hostname.startsWith('www.')) return Response.redirect('https://abduraximov.uz' + p + u.search, 301);
    try {
      if (p === '/api/geo') return await geo(req, env, ctx);
      if (p.startsWith('/api/admin/')) return await admin(req, env, p);
      if (p.startsWith('/bot/') && req.method === 'POST') return env.GEO_BOT_TOKEN && p === '/bot/' + await hookSecret(env) ? await hook(req, env) : new Response('no', { status: 404 });
      if (p === '/bot-setup') {
        if (!env.GEO_BOT_TOKEN) return J({ error: 'no_token' }, 503);
        const r = await tg(env, 'setWebhook', { url: 'https://abduraximov.uz/bot/' + await hookSecret(env), secret_token: await hookSecret(env), allowed_updates: ['message'], drop_pending_updates: true });
        const j = await r.json().catch(() => ({})); return J({ ok: !!j.ok, bot: await botName(env), description: j.description });
      }
    } catch (e) { return J({ error: 'server' }, 500); }
    if (p === '/robots.txt') return new Response('User-agent: *\nAllow: /\nDisallow: /admin\nSitemap: https://abduraximov.uz/sitemap.xml\n', { headers: { 'content-type': 'text/plain' } });
    if (p === '/sitemap.xml') return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://abduraximov.uz/</loc></url><url><loc>https://abduraximov.uz/maxfiylik</loc></url></urlset>', { headers: { 'content-type': 'application/xml' } });
    if (req.method !== 'GET' && req.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
    if (p === '/maxfiylik' || p === '/maxfiylik/') return new Response(req.method === 'HEAD' ? null : LEGAL, { headers: SEC });
    if (p === '/shartlar' || p === '/shartlar/') return Response.redirect('https://abduraximov.uz/maxfiylik#shartlar', 302);
    if (p === '/xavfsizlik' || p === '/huquqiy') return Response.redirect('https://abduraximov.uz/maxfiylik#xavfsizlik', 302);
    if (p === '/admin' || p === '/admin/') return new Response(ADMIN, { headers: Object.assign({}, SEC, { 'x-robots-tag': 'noindex, nofollow', 'cache-control': 'no-store' }) });
    if (p !== '/' && p !== '/index.html') return Response.redirect('https://' + u.hostname + '/', 302);
    return home(req, env);
  }
};
